window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-28001\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεμεσσητός, νέμεσσις</h1><div class=\"entry-meta\"><span>DGP · ordem 227 na letra ν · nº geral 28001</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = νεμεσητός, νέμεσις.</p></section></article>\n<article id=\"entry-dgp-28002\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεμέτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 228 na letra ν · nº geral 28002</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que distribui a justiça; vingador; juiz, epít. de Zeus. 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28003\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέμηαι</h1><div class=\"entry-meta\"><span>DGP · ordem 229 na letra ν · nº geral 28003</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a sing. pres. subj. méd. poét. de νέμω.</p></section></article>\n<article id=\"entry-dgp-28004\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέμησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 230 na letra ν · nº geral 28004</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 distribuição; repartição 2 rar. extensão (territorial). 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28005\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέμος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 231 na letra ν · nº geral 28005</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pastagem 2 bosque. 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28006\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέμω</h1><div class=\"entry-meta\"><span>DGP · ordem 232 na letra ν · nº geral 28006</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. νεμῶ, aor. ἔνειμα, perf. νενέμηκα; méd. fut. νεμοῦμαι, aor. ἐνειμάμην e ἐνεμησάμην) ativo 1 dar como parte; partilhar; distribuir algo, ac., a alguém, dat. 2 dispensar; outorgar; atribuir; destinar algo, ac., a alguém, dat.; πλέον (μέρος) νέμειν dar muita importância a 3 permitir; consentir; admitir, inf. 4 conduzir ao pasto; fazer pastar 5 possuir; ocupar; habitar 6 dirigir; governar; gerenciar; administrar, ac. ou dat. 7 manejar; guiar 8 olhar como; considerar alguém ou algo, ac., predic., ac. 9 tomar por; admitir como; designar como média 10 dividir; distribuir; partilhar entre si 11 administrar; explorar para si; usufruir de; ter; possuir 12 viver em; habitar; ocupar 13 ter como quinhão; ter como destino; passar o tempo; viver 14 ir ao pasto; pastar; nutrir-se de, ac.; (fogo, tumor) devorar passiva 15 ser local de pastagem 16 (país) ser regido por determinado costume; viver de acordo com, dat. 17 ser habitado; ser residência de 1 κρέα δαίετο καὶ νέμε μοίρας hom. ele cortava as carnes e distribuía as partes, τρίτον μέρος νείμαντες τῶν σκύλων tuc. após terem distribuído um terço do saque 2 Ζεὺς νέμει ὄλβον ἀνθρώποισιν hom. Zeus distribui a prosperidade aos homens, τιμὴν καὶ τροφὴν νέμετε plat. vós concedeis honra e meios de vida, Σόλων μὲν δὴ εὐδαιμονίης δευτερεῖα ἔνεμε τούτοισι her. assim atribuía Sólon a esses [jovens] o segundo lugar em felicidade, ἂν τὸ σὸν γέρας τιμὴν ἐμοὶ νείμειεν ἣν σὲ χρῆν ἔχειν sóf. talvez o prêmio que recebeste me conceda a glória que devia ser tua, νομοθέτῃ κολαστὴν τῶν ἁμαρτημάτων θάνατον ἀνάγκη νέμειν plat. é imperioso que o legislador atribua a pena de morte como punição das faltas, ἐπεὶ δὲ ταρβεῖς τῷ τ’ ὄχλῳ πλέον νέμεις eur. já que tens medo e dás mais importância para a multidão, πότερα δ’ ἄν εἰ νέμοι τις αἵρεσιν, λάβοις; sóf. se alguém te concedesse a escolha, qual preferirias? 3 οὔτε βαθεῖν κυλίκων νεῖμεν ἐμοὶ τέρψιν ὁμιλεῖν sóf. nem me deixou gozar do prazer das fundas taças 4 Πρωτεὺς φῶκας ἔνεμεν teócr. Proteu fazia pastar as focas, ποιμένες κτήνη πληγῇ νέμοντες plat. pastores que pastoreiam os animais com golpes, τὰ ὄρη νέμειν xen. fazer pastar nas montanhas, εἰ μέλλομεν ἱκανὴν χώραν ἕξειν νέμειν τε καὶ ἀροῦν plat. se queremos ter terra suficiente para destinar ao pastoreio e para arar 5 ἡ πρὸς τὴν ἠῶ τῆς Λιβύης, τὴν οἱ νομάδες νέμουσι her. a parte da Líbia voltada para o oriente, a qual os nômades habitam 6 ἀπέδεξαν τούτους μὲν τὴν πόλιν νέμειν her. a esses designaram para governar a cidade, ἐπί τε τοῖσι κατεστεῶσι ἔνεμε τὴν πόλιν κοσμέων καλῶς τε καὶ εὖ her. ele governou a cidade segundo o que estava estabelecido, administrando-a de maneira excelente, ὅς Συρακόσσαισι νέμει βασιλεύς pínd. ele que, como rei, governa os siracusanos, ἀστραπᾶν κράτη νέμων, ὦ Ζεῦ πάτερ sóf. ó Zeus pai, que governas a força dos raios 7 τοιαῦθ’ ὁ μάντις ἀσπίδ’ εὐκήλως νέμων πάγχαλκον ηὔδα ésql. tais coisas dizia o adivinho enquanto manejava tranqüilamente um escudo de bronze maciço 8 σὲ δ’ ἔγωγε νέμω θεόν sóf. eu te considero uma deusa, σ’ ἐγὼ μέγιστον Ἀργείων νέμω sóf. eu te considero o maior dos argivos, ἥμαρτον, εἴ τι τῶνδ’ ἁμαρτίαν νέμεις sóf. eu errei, se consideras erro um desses meus gestos 9 ἀλλὰ νέμειν ἀνάγκη προστάτην artt. mas é imperioso que [os metecos] escolham [alguém] como protetor, οἱ νενεμημένοι pol. os admitidos entre os inscritos na lista como cidadãos 10 νειμάσθων μὲν δὴ πρῶτον γῆν τε καὶ οἰκίας plat. que eles (os colonos) dividam entre si primeiramente a terra e as casas 11 πατρώϊα πάντα νέμεσθαι hom. usufruir de todos os bens paternos, καὶ τέμενος νεμόμεσθα μέγα Ξάνθοιο παρ’ ὄχθας hom. e um grande terreno possuimos junto das margens do Xanto 12 ὅσα ζῷα κατὰ ποταμοὺς καὶ ἐν τοῖς πεδίοιος νέμεται plat. todos os animais que vivem perto de rios e nas planícies, ἄλσεα καλὰ νέμονται hom. [as ninfas] habitam belos bosques, οἳ νεμόνεσθ’ Ἰθάκην hom. nós que habitamos Ítaca 13 ἄδακρυν νέμονται αἰῶνα pínd. vivem uma vida sem lágrimas, ἁμέραν τὰν μὲν παρὰ πατρὶ φίλῳ ∆ὶ νέμονται, τὰν δ’ ὑπὸ κεύθεσι γαίας pínd. um dia eles [os Dióscuros] passam junto do caro pai Zeus, e o outro nas profundezas da terra 14 ἐν εἱαμενῇ ἕλεος μεγάλοιο νέμονται hom. [vacas] que pastam em pradaria de extenso palude, οἱ Παίονες ἔφασαν νεμο­μέ­νας ἁρπασθῆναι her. os peones disseram que [as éguas] tinham sido roubadas enquanto pastavam, τὴν καλὴν νομὴν ν. sept. pastar em bom pasto, πολὺ πρῶτος νέμεαι τέρεν’ ἄνθεα ποίης hom. és o primeiríssimo a nutrir-te das tenras flores do prado 15 ὄρος νέμεται αἰξὶ καὶ βουσί xen. a montanha é lugar de pastagem para as cabras e as vacas 16 μέχρι τοῦδε πολλὰ τῆς Ἑλλάδος τῷ παλαιῷ τρόπῳ νέμεται tuc. até agora grande parte da Hélada vive de acordo com esse costume antigo. 17 πάντα ὑπὸ βαρβάροισι νέμεται her. toda região é ocupada pelos bárbaros.</p></section></article>\n<article id=\"entry-dgp-28007\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νένασμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 233 na letra ν · nº geral 28007</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de ναίω e de νάσσω.</p></section></article>\n<article id=\"entry-dgp-28008\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νένησμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 234 na letra ν · nº geral 28008</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. νέω4.</p></section></article>\n<article id=\"entry-dgp-28009\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νένιπται</h1><div class=\"entry-meta\"><span>DGP · ordem 235 na letra ν · nº geral 28009</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. perf. pas. de νίπτω.</p></section></article>\n<article id=\"entry-dgp-28010\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νένωμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 236 na letra ν · nº geral 28010</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. jôn. de νοέω.</p></section></article>\n<article id=\"entry-dgp-28011\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοάλωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 237 na letra ν · nº geral 28011</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-tomado. 〈νέος, ἁλισκομαι〉</p></section></article>\n<article id=\"entry-dgp-28012\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοαρδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 238 na letra ν · nº geral 28012</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-irrigado. 〈νέος, ἄρδω〉</p></section></article>\n<article id=\"entry-dgp-28013\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόγαμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 239 na letra ν · nº geral 28013</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-casado. 〈νέος, γαμέω〉</p></section></article>\n<article id=\"entry-dgp-28014\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεογενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 240 na letra ν · nº geral 28014</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-nascido. 〈νέος, γένος〉</p></section></article>\n<article id=\"entry-dgp-28015\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεογιλός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 241 na letra ν · nº geral 28015</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recém-nascido 2 de curta duração.</p></section></article>\n<article id=\"entry-dgp-28016\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεογνός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 242 na letra ν · nº geral 28016</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-nascido. 〈νέος, γίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-28017\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοδαμώδης, ης, εν</h1><div class=\"entry-meta\"><span>DGP · ordem 243 na letra ν · nº geral 28017</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-admitido como cidadão entre os cidadãos. 〈νέος, δῆμος〉</p></section></article>\n<article id=\"entry-dgp-28018\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόδαρτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 244 na letra ν · nº geral 28018</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-esfolado (pele). 〈νέος, δείρω〉</p></section></article>\n<article id=\"entry-dgp-28019\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοδίδακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 245 na letra ν · nº geral 28019</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">representado há pouco (peça). 〈νέος, διδάσκω〉</p></section></article>\n<article id=\"entry-dgp-28020\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοδμής, ῆτος</h1><div class=\"entry-meta\"><span>DGP · ordem 246 na letra ν · nº geral 28020</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 recém-subjugado 2 recém-casado; de casamento recente. 〈νέος, δαμάω〉</p></section></article>\n<article id=\"entry-dgp-28021\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόδμητος1, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 247 na letra ν · nº geral 28021</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recém-subjugado, i.e., morto há pouco 2 fem. recém-casada. 〈νέος, δαμάω〉</p></section></article>\n<article id=\"entry-dgp-28022\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόδμητος2, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 248 na letra ν · nº geral 28022</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-construído. 〈νέος, δέμω〉</p></section></article>\n<article id=\"entry-dgp-28023\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοδρεπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 249 na letra ν · nº geral 28023</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νεόδρεπτος.</p></section></article>\n<article id=\"entry-dgp-28024\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόδρεπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 250 na letra ν · nº geral 28024</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-colhido; fresco. 〈νέος, δρέπω〉</p></section></article>\n<article id=\"entry-dgp-28025\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόδρομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 251 na letra ν · nº geral 28025</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que há pouco ainda corria: νεοδρόμῳ λαβὼν θήρῃ bábrio tendo capturado uma fera que há pouco corria, i.e., fera recém-capturada. 〈νέος, δρόμος〉</p></section></article>\n<article id=\"entry-dgp-28026\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόδροπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 252 na letra ν · nº geral 28026</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νεόδρεπτος.</p></section></article>\n<article id=\"entry-dgp-28027\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοζυγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 253 na letra ν · nº geral 28027</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recentemente colocado sob jugo; recém-atrelado (animal) 2 recentemente posto sob o jugo (do casamento). 〈νέος, ζυγόν〉</p></section></article>\n<article id=\"entry-dgp-28028\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόζυγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 254 na letra ν · nº geral 28028</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-casado. 〈νέος, ζυγόν〉</p></section></article>\n<article id=\"entry-dgp-28029\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοθαλής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 255 na letra ν · nº geral 28029</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = νεοθηλής2.</p></section></article>\n<article id=\"entry-dgp-28030\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 256 na letra ν · nº geral 28030</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 há pouco tempo; recentemente 2 do fundo; da base. 〈νέος, -θεν〉</p></section></article>\n<article id=\"entry-dgp-28031\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόθηκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 257 na letra ν · nº geral 28031</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-afiado. 〈νέος, θήγω〉</p></section></article>\n<article id=\"entry-dgp-28032\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοθηλής1, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 258 na letra ν · nº geral 28032</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que mama há pouco tempo; recém-nas­cido. 〈νέος, θηλή〉</p></section></article>\n<article id=\"entry-dgp-28033\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοθηλής2, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 259 na letra ν · nº geral 28033</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 florido há pouco 2 recém-nascido (animal) 3 recente. 〈νέος, θάλλω〉</p></section></article>\n<article id=\"entry-dgp-28034\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοθηλός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 260 na letra ν · nº geral 28034</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νεοθηλής2.</p></section></article>\n<article id=\"entry-dgp-28035\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 261 na letra ν · nº geral 28035</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a pl. pres. opt. méd. ép. de νέω1.</p></section></article>\n<article id=\"entry-dgp-28036\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 262 na letra ν · nº geral 28036</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ardor juvenil; loucura da juventude. 〈νέος〉</p></section></article>\n<article id=\"entry-dgp-28037\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοκατάστατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 263 na letra ν · nº geral 28037</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-estabelecido. 〈νέος, καθίσ­τημι〉</p></section></article>\n<article id=\"entry-dgp-28038\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοκόνητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 264 na letra ν · nº geral 28038</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-derramado (sangue). 〈νέος, κονέω〉</p></section></article>\n<article id=\"entry-dgp-28039\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόκοτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 265 na letra ν · nº geral 28039</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de procedência recente; novo.</p></section></article>\n<article id=\"entry-dgp-28040\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοκράς, άτος</h1><div class=\"entry-meta\"><span>DGP · ordem 266 na letra ν · nº geral 28040</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) = νεόκρατος.</p></section></article>\n<article id=\"entry-dgp-28041\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόκρατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 267 na letra ν · nº geral 28041</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 misturado há pouco (vinho) 2 que há pouco se juntou ao grupo (amigo). 〈νέος, κεράννυμι〉</p></section></article>\n<article id=\"entry-dgp-28042\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόκτιστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 268 na letra ν · nº geral 28042</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-construído. 〈νέος, κτίζω〉</p></section></article>\n<article id=\"entry-dgp-28043\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεολαία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 269 na letra ν · nº geral 28043</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">juventude; grupo de jovens. 〈νέος, λαός〉</p></section></article>\n<article id=\"entry-dgp-28044\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 270 na letra ν · nº geral 28044</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. νέω1.</p></section></article>\n<article id=\"entry-dgp-28045\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεομηνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 271 na letra ν · nº geral 28045</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = νουμηνία.</p></section></article>\n<article id=\"entry-dgp-28046\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόνυμφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 272 na letra ν · nº geral 28046</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-casado. 〈νέος, νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28047\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοπαγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 273 na letra ν · nº geral 28047</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se tornou sólido recentemente; de consistência recente. 〈νέος, πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-28048\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοπαθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 274 na letra ν · nº geral 28048</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que sofreu há pouco; cujo sofrimento é inaudito, recente. 〈νέος, πάθος〉</p></section></article>\n<article id=\"entry-dgp-28049\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοπενθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 275 na letra ν · nº geral 28049</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que sofre ou chora uma dor recente. 〈νέος, πένθος〉</p></section></article>\n<article id=\"entry-dgp-28050\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόπλουτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 276 na letra ν · nº geral 28050</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ficou rico recentemente; novo rico. 〈νέος, πλοῦτος〉</p></section></article>\n<article id=\"entry-dgp-28051\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόπλυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 277 na letra ν · nº geral 28051</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-lavado; limpado há pouco. 〈νέος, πλύνω〉</p></section></article>\n<article id=\"entry-dgp-28052\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόποκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 278 na letra ν · nº geral 28052</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-tosquiado. 〈νέος, πέκω〉</p></section></article>\n<article id=\"entry-dgp-28053\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοπρεπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 279 na letra ν · nº geral 28053</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que convém à juventude 2 que parece jovem; que ostenta ares juvenis 3 impulsivo. 〈νέος, πρέπω〉</p></section></article>\n<article id=\"entry-dgp-28054\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόπριστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 280 na letra ν · nº geral 28054</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recentemente cortado. 〈νέος, πρίω1〉</p></section></article>\n<article id=\"entry-dgp-28055\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νεοπτόλεμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 281 na letra ν · nº geral 28055</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Neoptólemo, filho de Aquiles. 〈νέος, πτόλεμος〉</p></section></article>\n<article id=\"entry-dgp-28056\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόπτολις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 282 na letra ν · nº geral 28056</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nova cidade. 〈νέος, πτόλις〉</p></section></article>\n<article id=\"entry-dgp-28057\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόρραντος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 283 na letra ν · nº geral 28057</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-derramado (sangue, lágrima). 〈νέος, ῥαίνω〉</p></section></article>\n<article id=\"entry-dgp-28058\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόρρυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 284 na letra ν · nº geral 28058</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que começou a escorrer há pouco tempo (sangue) 2 que ainda escorre; ainda gotejante. 〈νέος, ῥέω〉</p></section></article>\n<article id=\"entry-dgp-28059\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέορτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 285 na letra ν · nº geral 28059</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que acaba de surgir; novo; recente; jovem. 〈νέος, ὄρνυμι〉</p></section></article>\n<article id=\"entry-dgp-28060\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 286 na letra ν · nº geral 28060</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 novo; jovem: κοῦροι νέοι hom. jovens guerreiros, νέα κόρη longo menina nova 2 próprio de um jovem; da juventude; juvenil: νέοις ἐν ἀέθλοις pínd. nos jogos juvenis, νέαι διάνοιαι lís. pensamentos próprios de um jovem 3 novo; recente; fresco: μυχῷ θαλάμοιο νέοιο hom. no fundo do novo tálamo, οἶνος νέος hes. vinho novo, ἐκ νέης her. de novo 4 inesperado; incomum; estranho: νέους λόγους ésql. palavras estranhas, ποιέειν τι νεώτερον her. realizar algo extraordinário, νεώτερα πρήγματα πρήσσειν her. tentar introduzir novidades, i.e., tramar uma rebelião, νεώτερόν τι ποιεῖν ἐς ou περί τινα tomar medidas extraordinárias ou extremas contra alguém ♦ οἱ νέοι 5 os jovens: νέοι ἠδὲ γέροντες hom. os jovens e os velhos ♦ οἱ νεώτεροι 6 os jovens 7 os jovens em idade militar; os recrutas 8 os mais recentes; os modernos ♦ ἡ νέα 9 crist. o Novo Testamento ♦ τὸ νέον 10 a juventude: ἐκ νέου, ἐκ νέων plat. desde a juventude 11 col. a juventude; os juvens: τὸ νέον ἅπαν plat. toda a juventude 12 pl., bíbl. as primícias 13 crist. as coisas novas dos fatos relatados no Novo Testamento ♦ νέον e τὸ νέον adv. 14 recentemente; ultimamente; há pouco.</p></section></article>\n<article id=\"entry-dgp-28061\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεός1, οῦ (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 287 na letra ν · nº geral 28061</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">terra em alqueive.</p></section></article>\n<article id=\"entry-dgp-28062\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεός2</h1><div class=\"entry-meta\"><span>DGP · ordem 288 na letra ν · nº geral 28062</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. jôn. de ναῦς.</p></section></article>\n<article id=\"entry-dgp-28063\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόσμηκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 289 na letra ν · nº geral 28063</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recém-polido 2 recém-entalhado. 〈νέος, σμήχω〉</p></section></article>\n<article id=\"entry-dgp-28064\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσπαδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 290 na letra ν · nº geral 28064</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-tirado da bainha; desembainha­do há pouco. 〈νέος, σπάω〉</p></section></article>\n<article id=\"entry-dgp-28065\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσπάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 291 na letra ν · nº geral 28065</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) arrancado há pouco. 〈νέος, σπάω〉</p></section></article>\n<article id=\"entry-dgp-28066\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόσπορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 292 na letra ν · nº geral 28066</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semeado há pouco. 〈νεός, σπείρω〉</p></section></article>\n<article id=\"entry-dgp-28067\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσσεύω,</h1><div class=\"entry-meta\"><span>DGP · ordem 293 na letra ν · nº geral 28067</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. νεοττεύω 1 chocar no ninho; chocar 2 fazer um ninho. 〈νεοττός〉</p></section></article>\n<article id=\"entry-dgp-28068\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσσιά,</h1><div class=\"entry-meta\"><span>DGP · ordem 294 na letra ν · nº geral 28068</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. νεοττιά, ᾶς (ἡ) 1 ninho 2 colméia. 〈νεοττός〉</p></section></article>\n<article id=\"entry-dgp-28069\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσσίον,</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra ν · nº geral 28069</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. νεοττίον, ου (τό) 1 filhote de passarinho 2 gema de ovo. 〈νεοσσός〉</p></section></article>\n<article id=\"entry-dgp-28070\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσσός,</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra ν · nº geral 28070</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. νεοττός, οῦ (ὁ) 1 filhote; cria (de animal) 2 criança 3 gema do ovo. 〈νέος〉</p></section></article>\n<article id=\"entry-dgp-28071\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσσοτροφία,</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra ν · nº geral 28071</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. νεοττοτροφία, ας (ἡ) ação de nutrir os filhotes. 〈νεοσσός, τροφή〉</p></section></article>\n<article id=\"entry-dgp-28072\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσταθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra ν · nº geral 28072</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-estabelecido.</p></section></article>\n<article id=\"entry-dgp-28073\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόστροφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra ν · nº geral 28073</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-torcido (corda). 〈νέος, στρέφω〉</p></section></article>\n<article id=\"entry-dgp-28074\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσφαγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra ν · nº geral 28074</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-degolado. 〈νέος, σφάζω〉</p></section></article>\n<article id=\"entry-dgp-28075\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοτελής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra ν · nº geral 28075</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recém-iniciado 2 crist. recém-convertido ou recém-batizado. 〈νέος, τέλος〉</p></section></article>\n<article id=\"entry-dgp-28076\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεότευκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra ν · nº geral 28076</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-fabricado. 〈νέος, τεύχω〉</p></section></article>\n<article id=\"entry-dgp-28077\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοτευχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra ν · nº geral 28077</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νεότευκτος.</p></section></article>\n<article id=\"entry-dgp-28078\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra ν · nº geral 28078</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 juventude; idade jovem 2 ardor da juventude; espírito juvenil; impetuosidade 3 a juventude; os jovens; grupo de jovens. 〈νέος〉</p></section></article>\n<article id=\"entry-dgp-28079\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεότμητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra ν · nº geral 28079</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-cortado; recém-talhado. 〈νέος, τέμνω〉</p></section></article>\n<article id=\"entry-dgp-28080\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοτόκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra ν · nº geral 28080</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que acaba de dar à luz. 〈νέος, τίκτω〉</p></section></article>\n<article id=\"entry-dgp-28081\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεότομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra ν · nº geral 28081</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recém-cortado; recém-fendido 2 recém-aberto (ferimento). 〈νέος, τέμνω〉</p></section></article>\n<article id=\"entry-dgp-28082\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοτρεφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra ν · nº geral 28082</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-nascido. 〈νέος, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-28083\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεότροφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra ν · nº geral 28083</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νεοτρεφής.</p></section></article>\n<article id=\"entry-dgp-28084\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοττεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra ν · nº geral 28084</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ninho. 〈νεοττεύω〉</p></section></article>\n<article id=\"entry-dgp-28085\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοττεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra ν · nº geral 28085</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = νεοσσεύω.</p></section></article>\n<article id=\"entry-dgp-28086\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοττοποιέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra ν · nº geral 28086</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. 1 fazer o ninho ♦ méd. 2 fazer o ninho; acomodar a ninhada.</p></section></article>\n<article id=\"entry-dgp-28087\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra ν · nº geral 28087</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito há pouco; recém-feito; recém-trabalhado. 〈νέος, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-28088\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεούτατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra ν · nº geral 28088</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-ferido. 〈νέος, οὐτάω〉</p></section></article>\n<article id=\"entry-dgp-28089\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόφυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra ν · nº geral 28089</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recém-plantado 2 recém-convertido; neófito (pessoa) 3 recém-incutido (na alma). 〈νέος, φύω〉</p></section></article>\n<article id=\"entry-dgp-28090\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοχάρακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra ν · nº geral 28090</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recém-gravado. 〈νέος, χαράσσω〉</p></section></article>\n<article id=\"entry-dgp-28091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοχμός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra ν · nº geral 28091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 novo; recente 2 novo; estranho. 〈νέος〉</p></section></article>\n<article id=\"entry-dgp-28092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοχμόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra ν · nº geral 28092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(pres. e aor. ἐνεόχμωσα) 1 renovar 2 inovar; mudar o estado das negociações, dos empreendimentos; produzir mudanças (políticas) 3 Medic. causar complicações. 〈νεοχμός〉</p></section></article>\n<article id=\"entry-dgp-28093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 319 na letra ν · nº geral 28093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor. ἐνέωσα) 1 renovar ♦ méd. (aor. ἐνεωσά­μην) 2 restaurar. 〈νέος〉</p></section></article>\n<article id=\"entry-dgp-28094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέπους, ποδος</h1><div class=\"entry-meta\"><span>DGP · ordem 320 na letra ν · nº geral 28094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) ger. pl. cujos pés são nadadeiras (foca, peixe)</p></section></article>\n<article id=\"entry-dgp-28095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέρθε, νέρθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 321 na letra ν · nº geral 28095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., poét. = ἔνερθε.</p></section></article>\n<article id=\"entry-dgp-28096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νερτεροδρόμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 322 na letra ν · nº geral 28096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">correio dos mortos. 〈νέρθε, δρόμος〉</p></section></article>\n<article id=\"entry-dgp-28097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέρτερος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 323 na letra ν · nº geral 28097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 que está embaixo; inferior 2 que está no mundo subterrâneo, nos infernos: νέρτεροι θεοί os deuses infernais ♦ οἱ νέρτεροι 3 os mortos ♦ τὰ νέρτερα 4 os infernos. 〈νέρθε〉</p></section></article>\n<article id=\"entry-dgp-28098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νέρων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 324 na letra ν · nº geral 28098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Nero, imperador romano.</p></section></article>\n<article id=\"entry-dgp-28099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νεστόρεος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 325 na letra ν · nº geral 28099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Nestor. 〈Νέστωρ〉</p></section></article>\n<article id=\"entry-dgp-28100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νεστορίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 326 na letra ν · nº geral 28100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho de Nestor. 〈Νέστωρ〉</p></section></article>\n";
